    ref as React.Ref<HTMLDivElement>,
    { inView, inViewOnce, inViewMargin },
  );

  const Component = asChild ? Slot : motion.div;

  return (
    <ParticlesProvider value={{ animate, isInView }}>
      <ReducedMotionConfig>
        <Component
          ref={localRef}
          style={{ position: 'relative', ...style }}
          {...props}
        >
          {children}
        </Component>
      </ReducedMotionConfig>
    </ParticlesProvider>
  );
}

type ParticlesEffectProps = Omit<HTMLMotionProps<'div'>, 'children'> & {
  side?: Side;
  align?: Align;
  count?: number;
  radius?: number;
  spread?: number;
  duration?: number;
  holdDelay?: number;
  sideOffset?: number;
  alignOffset?: number;
  delay?: number;
};

function ParticlesEffect({
  side = 'top',
  align = 'center',
  count = 6,
  radius = 30,
  spread = 360,
  duration = 0.8,
  holdDelay = 0.05,
  sideOffset = 0,
  alignOffset = 0,
  delay = 0,
  transition,
  style,
  ...props
}: ParticlesEffectProps) {
  const { animate, isInView } = useParticles();
  const reduce = useShouldReduceMotion();

  const isVertical = side === 'top' || side === 'bottom';
  const alignPct = align === 'start' ? '0%' : align === 'end' ? '100%' : '50%';

  const top = isVertical
    ? side === 'top'
      ? `calc(0% - ${sideOffset}px)`
      : `calc(100% + ${sideOffset}px)`
    : `calc(${alignPct} + ${alignOffset}px)`;

  const left = isVertical
    ? `calc(${alignPct} + ${alignOffset}px)`
    : side === 'left'
      ? `calc(0% - ${sideOffset}px)`
      : `calc(100% + ${sideOffset}px)`;

  const containerStyle: React.CSSProperties = {
    position: 'absolute',
    top,
    left,
    transform: 'translate(-50%, -50%)',
  };

  const fullCircle = spread % 360 === 0 && spread !== 0;
  const angleStep =
    (spread * (Math.PI / 180)) /
    (fullCircle ? Math.max(1, count) : Math.max(1, count - 1));

  return (
    <AnimatePresence>
      {animate &&
        isInView &&
        !reduce &&
        [...Array(count)].map((_, i) => {
          const angle = i * angleStep;
          const x = Math.round(Math.cos(angle) * radius * 100) / 100;
          const y = Math.round(Math.sin(angle) * radius * 100) / 100;

          return (
            <motion.div
              key={i}
              style={{ ...containerStyle, ...style }}
              initial={{ scale: 0, opacity: 0 }}
              animate={{
                x: `${x}px`,
                y: `${y}px`,
                scale: [0, 1, 0],
                opacity: [0, 1, 0],
              }}
              transition={{
                duration,
                delay: delay + i * holdDelay,
                ease: 'easeOut',
                ...transition,
              }}
              {...props}
            />
          );
        })}
    </AnimatePresence>
  );
}

export {
  Particles,
  ParticlesEffect,
  type ParticlesProps,
  type ParticlesEffectProps,
};

import type * as React from 'react';

const VISUALLY_HIDDEN: React.CSSProperties = {
  position: 'absolute',
  width: 1,
  height: 1,
  padding: 0,
  margin: -1,
  overflow: 'hidden',
  clip: 'rect(0, 0, 0, 0)',
  whiteSpace: 'nowrap',
  borderWidth: 0,
};

let segmenter: Intl.Segmenter | null | undefined;

function splitGraphemes(text: string): string[] {
  if (segmenter === undefined) {
    segmenter =
      typeof Intl !== 'undefined' && typeof Intl.Segmenter === 'function'
        ? new Intl.Segmenter(undefined, { granularity: 'grapheme' })
        : null;
  }
  if (!segmenter) return Array.from(text);
  return Array.from(segmenter.segment(text), (s) => s.segment);
}

type Grapheme = { id: string; label: string };

/** The next text's graphemes, keeping the ids of the ones it shares with the previous text, in order. */
function matchGraphemes(
  previous: readonly Grapheme[],
  labels: readonly string[],
  newId: () => string,
): Grapheme[] {
  const m = previous.length;
  const n = labels.length;
  const common = Array.from({ length: m + 1 }, () =>
    new Array<number>(n + 1).fill(0),
  );
  for (let i = m - 1; i >= 0; i--)
    for (let j = n - 1; j >= 0; j--)
      common[i]![j] =
        previous[i]!.label === labels[j]
          ? common[i + 1]![j + 1]! + 1
          : Math.max(common[i + 1]![j]!, common[i]![j + 1]!);
  const kept = new Map<number, Grapheme>();
  for (let i = 0, j = 0; i < m && j < n;) {
    if (previous[i]!.label === labels[j]) kept.set(j++, previous[i++]!);
    else if (common[i + 1]![j]! >= common[i]![j + 1]!) i++;
    else j++;
  }
  return labels.map((label, j) => kept.get(j) ?? { id: newId(), label });
}

/** Each grapheme's advance in the text as the font sets it, kerning included. */
function measureAdvances(mirror: Element, labels: readonly string[]) {
  const node = mirror.firstChild;
  if (!node) return [];
  const range = document.createRange();
  const lefts: number[] = [];
  let offset = 0;
  for (const label of labels) {
    range.setStart(node, offset);
    range.setEnd(node, offset + label.length);
    lefts.push(range.getBoundingClientRect().left);
    offset += label.length;
  }
  range.setStart(node, 0);
  range.setEnd(node, offset);
  const right = range.getBoundingClientRect().right;
  return lefts.map((left, i) => (lefts[i + 1] ?? right) - left);
}

export {
  VISUALLY_HIDDEN,
  splitGraphemes,
  matchGraphemes,
  measureAdvances,
  type Grapheme,
};

